from dataclasses import dataclass
from copy import deepcopy
from .errors import Refused, Conflict

@dataclass
class Decision:
    tenant: str
    subject: str
    plan: str
    digest: str
    snapshot: dict
    reviewer: str
    consumed: bool = False

class Reviews:
    def __init__(self):
        self.decisions = {}

    def record(self, reviewer, plan):
        self.decisions[(plan.tenant, plan.id)] = Decision(plan.tenant, plan.subject,
            plan.id, plan.digest(), plan.snapshot(), reviewer.subject)
        return {'plan': plan.id, 'revision': plan.revision, 'reviewer': reviewer.subject}

    def consume(self, principal, plan):
        decision = self.decisions.get((principal.tenant, plan.id))
        if decision is None or decision.subject != principal.subject:
            raise Refused('review')
        if decision.consumed:
            raise Conflict('review consumed')
        decision.consumed = True
        return deepcopy(decision.snapshot)

    def status(self, principal, plan):
        decision = self.decisions.get((principal.tenant, plan.id))
        return {'reviewed': decision is not None, 'consumed': decision.consumed if decision else False}

class Executor:
    def __init__(self, catalog, reviews, delivery):
        self.catalog = catalog
        self.reviews = reviews
        self.delivery = delivery

    def execute(self, principal, plan):
        self.catalog.authorize(principal, plan.project)
        self.catalog.destination(plan.tenant, plan.destination)
        self.reviews.consume(principal, plan)
        document = self.catalog.read(plan.tenant, plan.project, plan.document)
        payload = document if plan.projection == 'full' else {'title': document['title']}
        return self.delivery.send(plan.tenant, plan.destination, payload)

from .models import Principal
from .errors import Refused

class Credentials:
    def __init__(self):
        self.entries = {
            'desk-write': Principal('mira', 'north', 'c101', frozenset({'read', 'write', 'run'})),
            'desk-view': Principal('mira', 'north', 'c102', frozenset({'read', 'run'})),
            'peer-write': Principal('noah', 'north', 'c103', frozenset({'read', 'write', 'run'})),
            'south-write': Principal('sora', 'south', 'c201', frozenset({'read', 'write', 'run'})),
            'operations': Principal('operator', 'north', 'c900', frozenset({'read', 'write', 'run', 'admin', 'approve'})),
        }
        self.disabled = set()

    def authenticate(self, token):
        if not isinstance(token, str):
            raise Refused('credential')
        principal = self.entries.get(token)
        if principal is None or principal.credential_id in self.disabled:
            raise Refused('credential')
        return principal

def require_scope(principal, scope):
    if scope not in principal.scopes:
        raise Refused('scope')

def require_tenant(principal, tenant):
    if principal.tenant != tenant:
        raise Refused('tenant')

from .identity import require_scope
from .validation import name

class Routes:
    def __init__(self, plans, reviews, catalog, executor):
        self.plans = plans
        self.reviews = reviews
        self.catalog = catalog
        self.executor = executor

    def create(self, request):
        require_scope(request.principal, 'write')
        project = name(request.arguments['project'])
        self.catalog.authorize(request.principal, project)
        self.catalog.destination(request.principal.tenant, name(request.arguments['destination']))
        return self.plans.create(request.principal, request.arguments)

    def update(self, request):
        require_scope(request.principal, 'write')
        return self.plans.update(request.principal, request.arguments)

    def inspect(self, request):
        plan = self.plans.owned(request.principal, name(request.arguments['plan']))
        return {'plan': plan.snapshot(), **self.reviews.status(request.principal, plan)}

    def review(self, request):
        require_scope(request.principal, 'approve')
        plan = self.plans.reviewable(request.principal, name(request.arguments['plan']))
        self.catalog.destination(plan.tenant, plan.destination)
        return self.reviews.record(request.principal, plan)

    def execute(self, request):
        require_scope(request.principal, 'run')
        plan = self.plans.owned(request.principal, name(request.arguments['plan']))
        return self.executor.execute(request.principal, plan)

from dataclasses import dataclass, asdict, replace
import hashlib
import json
from copy import deepcopy
from .errors import Missing, Refused, Conflict, Invalid
from .validation import name, text, integer

@dataclass(frozen=True)
class Plan:
    id: str
    tenant: str
    subject: str
    project: str
    document: str
    destination: str
    projection: str
    revision: int = 1

    def snapshot(self):
        return asdict(self)

    def digest(self):
        return hashlib.sha256(json.dumps(self.snapshot(), sort_keys=True).encode()).hexdigest()

class Plans:
    def __init__(self):
        self.rows = {}
        self.sequence = 0

    def create(self, principal, arguments):
        self.sequence += 1
        pid = 'plan-' + str(self.sequence)
        plan = Plan(pid, principal.tenant, principal.subject, name(arguments['project']),
                    name(arguments['document']), name(arguments['destination']),
                    self.projection(arguments.get('projection', 'title')))
        self.rows[pid] = plan
        return plan.snapshot()

    def projection(self, value):
        if value not in ('title', 'full'):
            raise Invalid('projection')
        return value

    def owned(self, principal, pid):
        plan = self.rows.get(pid)
        if plan is None:
            raise Missing('plan')
        if (plan.tenant, plan.subject) != (principal.tenant, principal.subject):
            raise Refused('plan owner')
        return plan

    def reviewable(self, principal, pid):
        plan = self.rows.get(pid)
        if plan is None:
            raise Missing('plan')
        if plan.tenant != principal.tenant:
            raise Refused('plan tenant')
        return plan

    def update(self, principal, arguments):
        plan = self.owned(principal, name(arguments['plan']))
        if plan.revision != integer(arguments['revision'], 1):
            raise Conflict('revision')
        updated = replace(plan, destination=name(arguments.get('destination', plan.destination)),
                          projection=self.projection(arguments.get('projection', plan.projection)),
                          revision=plan.revision + 1)
        self.rows[plan.id] = updated
        return updated.snapshot()

